/**
 * MediaPipe Face Landmarker wrapper (SOUP boundary).
 *
 * - WASM runtime is served from this app's origin (copied from node_modules),
 *   never from a CDN.
 * - The model is fetched as bytes so its SHA-256 can be computed and recorded
 *   in every assessment (configuration traceability) and, when a pinned hash
 *   is known, verified before use (integrity control RM-H07).
 */
import { FaceLandmarker, FilesetResolver, type FaceLandmarkerResult } from '@mediapipe/tasks-vision';
import type { FrameObservation, Pose } from '../core';
import type { EngineInfo } from '../data/types';
import { sha256Hex } from '../data/integrity';
import { faceLuminance } from './luminance';
import lock from './model-lock.json';

export const MODEL = {
  name: lock.name,
  localPath: 'models/face_landmarker.task',
  remoteUrl: lock.url,
  /** SHA-256 of the validated model build (model-lock.json). Any other model is refused. */
  pinnedSha256: lock.sha256 as string | null,
};

declare const __MP_VERSION__: string;

async function fetchModel(): Promise<{ bytes: Uint8Array; source: 'local' | 'remote' }> {
  try {
    const res = await fetch(new URL(MODEL.localPath, document.baseURI));
    const type = res.headers.get('content-type') ?? '';
    if (res.ok && !type.includes('text/html')) {
      const buf = new Uint8Array(await res.arrayBuffer());
      if (buf.byteLength > 1_000_000) return { bytes: buf, source: 'local' };
    }
  } catch {
    /* fall through to remote */
  }
  const res = await fetch(MODEL.remoteUrl);
  if (!res.ok) throw new Error(`model download failed (${res.status})`);
  return { bytes: new Uint8Array(await res.arrayBuffer()), source: 'remote' };
}

function poseFromMatrix(d: readonly number[]): Pose {
  // Detect storage order from where the translation lives (column-major: 12..14).
  const colMajor = Math.abs(d[12]!) + Math.abs(d[13]!) + Math.abs(d[14]!) >= Math.abs(d[3]!) + Math.abs(d[7]!) + Math.abs(d[11]!);
  const R = (r: number, c: number): number => (colMajor ? d[c * 4 + r]! : d[r * 4 + c]!);
  const deg = 180 / Math.PI;
  return {
    yaw: Math.asin(Math.max(-1, Math.min(1, -R(2, 0)))) * deg,
    pitch: Math.atan2(R(2, 1), R(2, 2)) * deg,
    roll: Math.atan2(R(1, 0), R(0, 0)) * deg,
  };
}

export class FaceEngine {
  private mode: 'VIDEO' | 'IMAGE' = 'VIDEO';
  private lastTs = 0;

  private constructor(
    private readonly lm: FaceLandmarker,
    readonly info: EngineInfo,
  ) {}

  static async create(onStatus?: (s: string) => void): Promise<FaceEngine> {
    onStatus?.('분석 엔진 불러오는 중…');
    const fileset = await FilesetResolver.forVisionTasks(new URL('mediapipe/wasm', document.baseURI).href);
    onStatus?.('얼굴 인식 모델 확인 중…');
    const { bytes, source } = await fetchModel();
    const sha = await sha256Hex(bytes);
    const integrity: EngineInfo['modelIntegrity'] = MODEL.pinnedSha256
      ? sha === MODEL.pinnedSha256
        ? 'verified'
        : 'mismatch'
      : 'unverified';
    if (integrity === 'mismatch') throw new Error('MODEL_INTEGRITY: model hash does not match the validated build');
    const options = (delegate: 'GPU' | 'CPU') => ({
      baseOptions: { modelAssetBuffer: bytes, delegate },
      runningMode: 'VIDEO' as const,
      numFaces: 1,
      outputFaceBlendshapes: true,
      outputFacialTransformationMatrixes: true,
    });
    let delegate: 'GPU' | 'CPU' = 'GPU';
    let lm: FaceLandmarker;
    try {
      lm = await FaceLandmarker.createFromOptions(fileset, options('GPU'));
    } catch {
      delegate = 'CPU';
      lm = await FaceLandmarker.createFromOptions(fileset, options('CPU'));
    }
    return new FaceEngine(lm, {
      runtime: `@mediapipe/tasks-vision@${__MP_VERSION__}`,
      model: MODEL.name,
      modelSha256: sha,
      modelSource: source,
      modelIntegrity: integrity,
      delegate,
    });
  }

  private async setMode(m: 'VIDEO' | 'IMAGE'): Promise<void> {
    if (this.mode !== m) {
      await this.lm.setOptions({ runningMode: m });
      this.mode = m;
    }
  }

  private toObservation(r: FaceLandmarkerResult, src: CanvasImageSource, w: number, h: number, t: number): FrameObservation {
    const face = r.faceLandmarks[0];
    if (!face) return { t, width: w, height: h, landmarks: [] };
    const landmarks = new Float32Array(face.length * 3);
    face.forEach((p, i) => {
      landmarks[3 * i] = p.x;
      landmarks[3 * i + 1] = p.y;
      landmarks[3 * i + 2] = p.z;
    });
    const m = r.facialTransformationMatrixes?.[0];
    const bs = r.faceBlendshapes?.[0]?.categories;
    return {
      t,
      width: w,
      height: h,
      landmarks,
      ...(m ? { pose: poseFromMatrix(m.data) } : {}),
      ...(bs ? { blendshapes: Object.fromEntries(bs.map((c) => [c.categoryName, c.score])) } : {}),
      luminance: faceLuminance(src, w, h, landmarks),
    };
  }

  async detectVideo(video: HTMLVideoElement): Promise<FrameObservation> {
    await this.setMode('VIDEO');
    const ts = Math.max(performance.now(), this.lastTs + 1);
    this.lastTs = ts;
    const r = this.lm.detectForVideo(video, ts);
    return this.toObservation(r, video, video.videoWidth, video.videoHeight, ts);
  }

  /**
   * Single-image detection. `mirrored` must be set for selfies saved as a
   * mirror image: the landmark topology is assigned by image position
   * (index 33 = image-left eye), so a mirrored photo would swap the
   * patient's sides. The image is flipped back before detection (RM-H09).
   */
  async detectImage(img: HTMLImageElement | HTMLCanvasElement | ImageBitmap, mirrored = false): Promise<FrameObservation> {
    if (mirrored) {
      const w0 = 'naturalWidth' in img ? img.naturalWidth : img.width;
      const h0 = 'naturalHeight' in img ? img.naturalHeight : img.height;
      const c = document.createElement('canvas');
      c.width = w0;
      c.height = h0;
      const ctx = c.getContext('2d')!;
      ctx.translate(w0, 0);
      ctx.scale(-1, 1);
      ctx.drawImage(img, 0, 0);
      img = c;
    }
    await this.setMode('IMAGE');
    const w = 'naturalWidth' in img ? img.naturalWidth : img.width;
    const h = 'naturalHeight' in img ? img.naturalHeight : img.height;
    return this.toObservation(this.lm.detect(img), img, w, h, performance.now());
  }
}

let enginePromise: Promise<FaceEngine> | null = null;

/** Lazily created singleton; a failed load can be retried. */
export function getEngine(onStatus?: (s: string) => void): Promise<FaceEngine> {
  if (!enginePromise) {
    enginePromise = FaceEngine.create(onStatus).catch((e: unknown) => {
      enginePromise = null;
      throw e;
    });
  }
  return enginePromise;
}
