/**
 * Face-region brightness and left/right lighting balance. Side lighting casts
 * shadows that shift landmarks asymmetrically, so it is gated (SRS-QC-004).
 */
const SIZE = 32;
let ctx: CanvasRenderingContext2D | null = null;

function context(): CanvasRenderingContext2D | null {
  if (!ctx) {
    const c = document.createElement('canvas');
    c.width = SIZE;
    c.height = SIZE;
    ctx = c.getContext('2d', { willReadFrequently: true });
  }
  return ctx;
}

export function faceLuminance(
  src: CanvasImageSource,
  w: number,
  h: number,
  lm: ArrayLike<number>,
): { mean: number; asymmetry: number } | undefined {
  const c = context();
  if (!c || lm.length < 468 * 3) return undefined;
  let x0 = 1;
  let y0 = 1;
  let x1 = 0;
  let y1 = 0;
  for (let i = 0; i < 468; i++) {
    const x = lm[3 * i]!;
    const y = lm[3 * i + 1]!;
    if (x < x0) x0 = x;
    if (x > x1) x1 = x;
    if (y < y0) y0 = y;
    if (y > y1) y1 = y;
  }
  // Inner 70 % of the face box: skin only, little background.
  const mx = (x1 - x0) * 0.15;
  const my = (y1 - y0) * 0.15;
  const sx = Math.max(0, (x0 + mx) * w);
  const sy = Math.max(0, (y0 + my) * h);
  const sw = Math.min(w - sx, (x1 - x0 - 2 * mx) * w);
  const sh = Math.min(h - sy, (y1 - y0 - 2 * my) * h);
  if (sw < 4 || sh < 4) return undefined;
  c.drawImage(src, sx, sy, sw, sh, 0, 0, SIZE, SIZE);
  const d = c.getImageData(0, 0, SIZE, SIZE).data;
  const g = new Float32Array(SIZE * SIZE);
  for (let i = 0; i < g.length; i++) g[i] = 0.299 * d[4 * i]! + 0.587 * d[4 * i + 1]! + 0.114 * d[4 * i + 2]!;
  // Split at the nose tip (landmark 1): its column for left/right, its row for upper/lower face.
  return lumaBalance(g, SIZE, Math.round(((lm[3]! * w - sx) / sw) * SIZE), Math.round(((lm[4]! * h - sy) / sh) * SIZE));
}

/**
 * Pure part: `g` is the n × n luma (0–255) of the inner face box; columns left of `splitX` are the image's left half,
 * rows above `splitY` the upper face. `asymmetry` = |L−R|/(L+R) (the gate, SRS-QC-004); `horiz` the same signed,
 * + = the image's right half brighter; `vert` + = the upper face brighter (2026-10-13, SRS-QC-010).
 */
export function lumaBalance(
  g: ArrayLike<number>,
  n: number,
  splitX: number,
  splitY: number,
): { mean: number; asymmetry: number; horiz: number; vert: number } {
  let a = 0;
  let na = 0;
  let b = 0;
  let nb = 0;
  let t = 0;
  let nt = 0;
  let u = 0;
  let nu = 0;
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++) {
      const l = g[y * n + x]!;
      if (x < splitX) {
        a += l;
        na++;
      } else {
        b += l;
        nb++;
      }
      if (y < splitY) {
        t += l;
        nt++;
      } else {
        u += l;
        nu++;
      }
    }
  const bal = (p: number, q: number) => (p + q > 0 ? (p - q) / (p + q) : 0);
  const la = na ? a / na : 0;
  const lb = nb ? b / nb : 0;
  const lt = nt ? t / nt : 0;
  const lu = nu ? u / nu : 0;
  return { mean: (a + b) / (na + nb), asymmetry: Math.abs(bal(la, lb)), horiz: bal(lb, la), vert: bal(lt, lu) };
}
